from pathlib import Path
import json,jsonschema
ROOT=Path(__file__).resolve().parents[3];S=ROOT/'lab/11_strategy_factory/schemas/saed_v4_09'
for p in S.glob('*.schema.json'):jsonschema.Draft202012Validator.check_schema(json.loads(p.read_text()))
pairs=[('execution_twin_profile.schema.json','lab/11_strategy_factory/examples/saed_v4_09/execution_twin_profile.json'),('execution_twin.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/GOLDEN_EXECUTION_TWIN.JSON'),('integrity_receipt.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/GOLDEN_INTEGRITY_RECEIPT.JSON'),('telemetry.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/GOLDEN_TELEMETRY.JSON'),('exposure_ledger.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/GOLDEN_EXPOSURE_LEDGER.JSON'),('twin_summary.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/GOLDEN_TWIN_SUMMARY.JSON'),('profile_registry.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/PROFILE_REGISTRY.JSON'),('scenario_manifest.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/GOLDEN_SCENARIO_MANIFEST.JSON'),('claim_ledger.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/CLAIM_LEDGER.JSON'),('replay_receipt.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/GOLDEN_REPLAY_RECEIPT.JSON'),('semantic_diff.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/GOLDEN_SEMANTIC_DIFF.JSON'),('conformance_results.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/CONFORMANCE_RESULTS.JSON'),('v4_09_to_v4_10_handoff.schema.json','lab/11_strategy_factory/artifacts/saed_v4_09/V4_09_TO_V4_10_HANDOFF.JSON')]
for schema,artifact in pairs:jsonschema.validate(json.loads((ROOT/artifact).read_text()),json.loads((S/schema).read_text()))
print(f'validated {len(list(S.glob("*.schema.json")))} schemas and {len(pairs)} artifacts')
